
  create table "public"."Sets" (
    "id" bigint generated by default as identity not null,
    "partido_id" bigint not null,
    "orden" numeric not null,
    "pareja1_jugador1_id" bigint not null,
    "pareja1_jugador2_id" bigint not null,
    "pareja2_jugador1_id" bigint not null,
    "pareja2_jugador2_id" bigint not null,
    "pareja1_juegos" numeric not null,
    "pareja2_juegos" numeric not null
      );


alter table "public"."Sets" enable row level security;

alter table "public"."Categorias" add column "puntos_set" numeric not null default '3'::numeric;

CREATE UNIQUE INDEX "Sets_pkey" ON public."Sets" USING btree (id);

alter table "public"."Sets" add constraint "Sets_pkey" PRIMARY KEY using index "Sets_pkey";

alter table "public"."Sets" add constraint "Sets_pareja1_jugador1_id_fkey" FOREIGN KEY (pareja1_jugador1_id) REFERENCES public."Socios"(id) not valid;

alter table "public"."Sets" validate constraint "Sets_pareja1_jugador1_id_fkey";

alter table "public"."Sets" add constraint "Sets_pareja1_jugador2_id_fkey" FOREIGN KEY (pareja1_jugador2_id) REFERENCES public."Socios"(id) not valid;

alter table "public"."Sets" validate constraint "Sets_pareja1_jugador2_id_fkey";

alter table "public"."Sets" add constraint "Sets_pareja2_jugador1_id_fkey" FOREIGN KEY (pareja2_jugador1_id) REFERENCES public."Socios"(id) not valid;

alter table "public"."Sets" validate constraint "Sets_pareja2_jugador1_id_fkey";

alter table "public"."Sets" add constraint "Sets_pareja2_jugador2_id_fkey" FOREIGN KEY (pareja2_jugador2_id) REFERENCES public."Socios"(id) not valid;

alter table "public"."Sets" validate constraint "Sets_pareja2_jugador2_id_fkey";

